@testable import AutoMobilePrototypeAgentCore
import Foundation
import XCTest

/// Swift port of the shared differential fuzz corpus (#14159). `fuzz-corpus.json` is generated by
/// `scripts/prototype/generate-bundle-fuzz-corpus.ts` and records the TypeScript verdict for every
/// case; the Swift importer must agree on accept/reject, code and path. The seeded generators below
/// add a deterministic robustness sweep (no trap, no foreign error type) on top of it.
enum PrototypeBundleFuzzFixtures {
    struct Corpus: Decodable, Sendable {
        let seed: Int
        let cases: [Case]
    }

    struct Case: Decodable, Sendable {
        let name: String
        let family: String
        let bundleBase64: Data
        let expect: String
        let code: String?
        let path: String?
    }

    /// Case name -> reason the Swift verdict is allowed to differ from the TypeScript one.
    static let knownDivergences: [String: String] = [:]

    static let corpus: Result<Corpus, Error> = Result {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        return try JSONDecoder().decode(Corpus.self, from: Data(
            contentsOf: root.appendingPathComponent("test/fixtures/prototype-bundle/fuzz-corpus.json")
        ))
    }
}

/// SplitMix64: tiny, reproducible, and independent of the platform RNG.
struct FuzzRandom {
    private var state: UInt64
    init(seed: UInt64) { state = seed }

    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var value = state
        value = (value ^ (value >> 30)) &* 0xBF58_476D_1CE4_E5B9
        value = (value ^ (value >> 27)) &* 0x94D0_49BB_1331_11EB
        return value ^ (value >> 31)
    }

    mutating func below(_ bound: Int) -> Int { Int(next() % UInt64(bound)) }
    mutating func pick<T>(_ items: [T]) -> T { items[below(items.count)] }
    mutating func chance(_ percent: Int) -> Bool { below(100) < percent }
}

/// Minimal ZIP assembler that, unlike `PrototypeBundleZipWriter`, can lie about every header field.
struct FuzzZipEntry {
    var name: String
    var packed: Data
    var expanded: Int
    var crc: UInt32
    var method = 0
    var flags = 0
    var attrs = 0

    static func stored(_ name: String, _ bytes: Data) -> FuzzZipEntry {
        .init(name: name, packed: bytes, expanded: bytes.count, crc: PrototypeBundleZipReader.crc32(bytes))
    }
}

enum FuzzZip {
    static func build(_ entries: [FuzzZipEntry]) -> Data {
        var locals = Data()
        var directory = Data()
        for entry in entries {
            let name = Data(entry.name.utf8)
            var local = [UInt8](repeating: 0, count: 30)
            put(&local, 0, 0x0403_4B50, 4)
            put(&local, 4, 20, 2)
            put(&local, 6, entry.flags, 2)
            put(&local, 8, entry.method, 2)
            put(&local, 12, 0x21, 2)
            put(&local, 14, Int(entry.crc), 4)
            put(&local, 18, entry.packed.count, 4)
            put(&local, 22, entry.expanded, 4)
            put(&local, 26, name.count, 2)
            var central = [UInt8](repeating: 0, count: 46)
            put(&central, 0, 0x0201_4B50, 4)
            put(&central, 4, 20, 2)
            put(&central, 6, 20, 2)
            put(&central, 8, entry.flags, 2)
            put(&central, 10, entry.method, 2)
            put(&central, 14, 0x21, 2)
            put(&central, 16, Int(entry.crc), 4)
            put(&central, 20, entry.packed.count, 4)
            put(&central, 24, entry.expanded, 4)
            put(&central, 28, name.count, 2)
            put(&central, 38, entry.attrs, 4)
            put(&central, 42, locals.count, 4)
            locals.append(contentsOf: local)
            locals.append(name)
            locals.append(entry.packed)
            directory.append(contentsOf: central)
            directory.append(name)
        }
        var end = [UInt8](repeating: 0, count: 22)
        put(&end, 0, 0x0605_4B50, 4)
        put(&end, 8, entries.count, 2)
        put(&end, 10, entries.count, 2)
        put(&end, 12, directory.count, 4)
        put(&end, 16, locals.count, 4)
        locals.append(directory)
        locals.append(contentsOf: end)
        return locals
    }

    private static func put(_ bytes: inout [UInt8], _ position: Int, _ value: Int, _ width: Int) {
        for index in 0 ..< width {
            bytes[position + index] = UInt8(truncatingIfNeeded: value >> (8 * index))
        }
    }

    /// Raw DEFLATE (fixed Huffman) for `1 + 258 * runs` zero bytes: one literal then max-length
    /// distance-1 matches. About 13 bits per 258 bytes, far above the 100:1 ratio cap.
    static func deflatedZeros(runs: Int) -> (packed: Data, expanded: Int) {
        var out = [UInt8]()
        out.reserveCapacity(runs * 13 / 8 + 8)
        var accumulator: UInt64 = 0
        var bitCount = 0
        // Huffman codes are packed most-significant bit first; header fields least-significant first.
        func emit(_ value: UInt64, _ width: Int) {
            accumulator |= value << UInt64(bitCount)
            bitCount += width
            while bitCount >= 8 {
                out.append(UInt8(truncatingIfNeeded: accumulator))
                accumulator >>= 8
                bitCount -= 8
            }
        }
        func reversed(_ value: UInt64, _ width: Int) -> UInt64 {
            (0 ..< width).reduce(0) { $0 | ((value >> UInt64($1)) & 1) << UInt64(width - 1 - $1) }
        }
        emit(1, 1) // BFINAL
        emit(1, 2) // BTYPE = fixed Huffman
        emit(reversed(0x30, 8), 8) // literal 0
        let match = reversed(0xC5, 8) | reversed(0, 5) << 8 // length 258 (symbol 285), distance 1
        for _ in 0 ..< runs {
            emit(match, 13)
        }
        emit(0, 7) // end of block
        if bitCount > 0 { out.append(UInt8(truncatingIfNeeded: accumulator)) }
        return (Data(out), 1 + 258 * runs)
    }
}

enum FuzzMutation {
    static let interesting: [UInt32] = [
        0, 1, 0xFF, 0xFFFF, 0x7FFF_FFFF, 0x8000_0000, 0xFFFF_FFFE, 0xFFFF_FFFF,
        0x0403_4B50, 0x0201_4B50, 0x0605_4B50, 0x0706_4B50,
    ]

    static func mutate(_ seed: Data, _ random: inout FuzzRandom) -> Data {
        var bytes = [UInt8](seed)
        for _ in 0 ..< 1 + random.below(3) where !bytes.isEmpty {
            let position = random.below(bytes.count)
            switch random.below(9) {
            case 0: bytes[position] ^= UInt8(1 << random.below(8))
            case 1: bytes[position] = UInt8(random.below(256))
            case 2: bytes.removeSubrange(position...)
            case 3: bytes.insert(
                    contentsOf: (0 ..< 1 + random.below(16)).map { _ in UInt8(random.below(256)) },
                    at: position
                )
            case 4: bytes.removeSubrange(position ..< min(bytes.count, position + 1 + random.below(16)))
            case 5:
                let end = min(bytes.count, position + 1 + random.below(64))
                bytes.insert(contentsOf: bytes[position ..< end], at: random.below(bytes.count))
            case 6: lie(&bytes, position, width: 4, &random)
            case 7: lie(&bytes, position, width: 2, &random)
            default: bytes.append(contentsOf: bytes.prefix(1 + random.below(32)))
            }
        }
        return Data(bytes)
    }

    /// Overwrites a little-endian u16/u32 header field at `offset` with a boundary value.
    private static func lie(_ bytes: inout [UInt8], _ offset: Int, width: Int, _ random: inout FuzzRandom) {
        guard offset + width <= bytes.count else { return }
        let value = random.pick(interesting)
        for index in 0 ..< width {
            bytes[offset + index] = UInt8(truncatingIfNeeded: value >> UInt32(8 * index))
        }
    }
}

final class PrototypeBundleFuzzTests: XCTestCase {
    override static func setUp() {
        super.setUp()
        _ = PrototypeBundleFixtures.corpus
        _ = PrototypeBundleFuzzFixtures.corpus
    }

    // MARK: - Shared differential corpus

    private func differential(_ range: Range<Int>) throws {
        let cases = try PrototypeBundleFuzzFixtures.corpus.get().cases
        XCTAssertEqual(cases.count, 360)
        for fixture in cases[range] where PrototypeBundleFuzzFixtures.knownDivergences[fixture.name] == nil {
            do {
                _ = try PrototypeBundle.read(fixture.bundleBase64)
                XCTAssertEqual(fixture.expect, "accept", fixture.name)
            } catch let error as PrototypeBundleFailure {
                XCTAssertEqual(fixture.expect, "reject", "\(fixture.name): \(error)")
                XCTAssertEqual(error.code.rawValue, fixture.code, fixture.name)
                XCTAssertEqual(
                    error.path.map { Data($0.utf8) },
                    fixture.path.map { Data($0.utf8) },
                    fixture.name
                )
            } catch {
                XCTFail("\(fixture.name): non-bundle error \(error)")
            }
        }
    }

    func testCorpusMetadata() throws {
        let corpus = try PrototypeBundleFuzzFixtures.corpus.get()
        XCTAssertEqual(corpus.seed, 14159)
        XCTAssertEqual(Set(corpus.cases.map(\.name)).count, corpus.cases.count)
        XCTAssertEqual(Set(corpus.cases.map(\.family)), ["bytes", "structural", "json"])
        let codes = Set(PrototypeBundleCode.allCases.map(\.rawValue))
        XCTAssertTrue(corpus.cases.compactMap(\.code).allSatisfy(codes.contains))
    }

    func testDifferentialCases000Through039() throws { try differential(0 ..< 40) }
    func testDifferentialCases040Through079() throws { try differential(40 ..< 80) }
    func testDifferentialCases080Through119() throws { try differential(80 ..< 120) }
    func testDifferentialCases120Through159() throws { try differential(120 ..< 160) }
    func testDifferentialCases160Through199() throws { try differential(160 ..< 200) }
    func testDifferentialCases200Through239() throws { try differential(200 ..< 240) }
    func testDifferentialCases240Through279() throws { try differential(240 ..< 280) }
    func testDifferentialCases280Through319() throws { try differential(280 ..< 320) }
    func testDifferentialCases320Through359() throws { try differential(320 ..< 360) }

    // MARK: - Seeded mutation sweep

    /// Reading must never trap, and may only throw the closed-vocabulary `PrototypeBundleFailure`.
    private func assertTotal(_ bytes: Data, _ label: String) {
        do {
            _ = try PrototypeBundle.read(bytes)
        } catch let error as PrototypeBundleFailure {
            XCTAssertTrue(PrototypeBundleCode.allCases.contains(error.code), "\(label): \(error)")
        } catch {
            XCTFail("\(label): non-bundle error \(error)")
        }
    }

    private func mutationSweep(salt: UInt64, iterations: Int) throws {
        let corpus = try PrototypeBundleFixtures.corpus.get().cases
        let seeds = [0, 1, 2, 3, 4, 5, 6].map { corpus[$0].bundleBase64 }
        let base = try UInt64(PrototypeBundleFuzzFixtures.corpus.get().seed)
        var random = FuzzRandom(seed: base &+ salt)
        for iteration in 0 ..< iterations {
            assertTotal(FuzzMutation.mutate(random.pick(seeds), &random), "salt \(salt) iteration \(iteration)")
        }
    }

    func testMutationSweepA() throws { try mutationSweep(salt: 1, iterations: 100) }
    func testMutationSweepB() throws { try mutationSweep(salt: 2, iterations: 100) }
    func testMutationSweepC() throws { try mutationSweep(salt: 3, iterations: 100) }

    func testRandomBytesAndTinyInputsNeverTrap() {
        var random = FuzzRandom(seed: 14159)
        assertTotal(Data(), "empty")
        for length in [1, 2, 3, 4, 21, 22, 23, 45, 46, 47, 64, 1000] {
            assertTotal(Data((0 ..< length).map { _ in UInt8(random.below(256)) }), "random \(length)")
        }
        let end = Data([0x50, 0x4B, 0x05, 0x06] + [UInt8](repeating: 0, count: 18))
        assertTotal(end, "empty eocd")
        assertTotal(Data(repeating: 0xFF, count: 22) + end, "ff prefix eocd")
        assertTotal(Data(repeating: 0x50, count: 70000), "repeated PK")
    }

    func testStructuralMutationsOfEntryTable() throws {
        let entries = try seedEntries()
        var random = FuzzRandom(seed: 14159 &+ 4)
        let names = ["spec.json", "bundle.json", "../spec.json", "/spec.json", "assets/../spec.json", "a.png", ""]
        for iteration in 0 ..< 120 {
            var table = entries
            for _ in 0 ..< 1 + random.below(3) {
                let index = random.below(table.count)
                switch random.below(8) {
                case 0: table[index].name = random.pick(names)
                case 1: table.append(table[index])
                case 2: table[index].attrs = Int(random.pick([0, 0x81A4_0000, 0xA1FF_0000, 0x1000_0000, 0x10]))
                case 3: table[index].method = random.pick([0, 8, 1, 9, 99])
                case 4: table[index].flags = random.pick([0, 1, 8, 0x40, 0x800, 0x808, 0xFFFF])
                case 5: table[index].expanded = Int(random.pick(FuzzMutation.interesting))
                case 6: table[index].crc = random.pick(FuzzMutation.interesting)
                default: table[index].packed = table[index].packed.prefix(random.below(table[index].packed.count + 1))
                }
            }
            assertTotal(FuzzZip.build(table), "structural \(iteration)")
        }
    }

    // MARK: - Hostile archives

    private func seedEntries() throws -> [FuzzZipEntry] {
        try PrototypeBundleZipReader.read(PrototypeBundleFixtures.corpus.get().cases[0].bundleBase64)
            .map { FuzzZipEntry.stored($0.0, $0.1) }
    }

    private func rejection(_ bytes: Data, _ label: String) -> PrototypeBundleFailure? {
        do {
            _ = try PrototypeBundle.read(bytes)
            XCTFail("\(label): expected rejection")
            return nil
        } catch let error as PrototypeBundleFailure {
            return error
        } catch {
            XCTFail("\(label): non-bundle error \(error)")
            return nil
        }
    }

    func testRebuiltSeedArchiveIsAccepted() throws {
        let entries = try seedEntries()
        XCTAssertEqual(entries.map(\.name), ["bundle.json", "spec.json"])
        XCTAssertNoThrow(try PrototypeBundle.read(FuzzZip.build(entries)))
    }

    func testHostileEntryNamesRejectWithNameCodes() throws {
        let entries = try seedEntries()
        let forbidden = [
            "../spec.json", "/spec.json", "./../spec.json", "assets/../spec.json", "assets\\a.png",
            "assets/\u{0}.png", "assets/é.png", "__MACOSX/spec.json", "assets/", "C:\\spec.json",
        ]
        for name in forbidden {
            let error = rejection(FuzzZip.build(entries + [.stored(name, Data())]), name)
            XCTAssertEqual(error?.code, .entryNameForbidden, name)
        }
        let notAllowed = [
            "BUNDLE.JSON.bak", "spec.json ", "spec.json.", "library.json", "",
            String(repeating: "a", count: 5000), "assets/\(String(repeating: "A", count: 64)).png",
            "fonts/\(String(repeating: "0", count: 63)).ttf",
        ]
        for name in notAllowed {
            let error = rejection(FuzzZip.build(entries + [.stored(name, Data())]), name)
            XCTAssertEqual(error?.code, .entryNotAllowed, name)
        }
    }

    func testDuplicateEntriesRejectCaseInsensitively() throws {
        let entries = try seedEntries()
        for twin in ["spec.json", "SPEC.JSON", "Spec.Json"] {
            let archive = FuzzZip.build(entries + [.stored(twin, Data())])
            XCTAssertEqual(rejection(archive, twin)?.code, .duplicateEntry, twin)
        }
    }

    func testSpecialFileAttributesRejectAsLinks() throws {
        for attrs in [0xA1FF_0000, 0xA000_0000, 0x1000_0000, 0x4000_0000, 0xC000_0000, 0x6000_0000, 0x10] {
            var entries = try seedEntries()
            entries[1].attrs = attrs
            XCTAssertEqual(rejection(FuzzZip.build(entries), "\(attrs)")?.code, .linkEntry, "\(attrs)")
        }
        var regular = try seedEntries()
        regular[1].attrs = 0x81A4_0000
        XCTAssertNoThrow(try PrototypeBundle.read(FuzzZip.build(regular)))
    }

    func testOversizeDeclaredEntriesReject() throws {
        for expanded in [PrototypeBundle.maxSpecBytes + 1, 2 << 20, 0x7FFF_FFFF, 0xFFFF_FFFE] {
            var entries = try seedEntries()
            entries[1].expanded = expanded
            XCTAssertEqual(rejection(FuzzZip.build(entries), "\(expanded)")?.code, .entryTooLarge, "\(expanded)")
        }
        var manifest = try seedEntries()
        manifest[0].expanded = PrototypeBundle.maxManifestBytes + 1
        XCTAssertEqual(rejection(FuzzZip.build(manifest), "manifest")?.code, .entryTooLarge)
    }

    private func bombRejects(mebibytes: Int) throws {
        let (packed, expanded) = FuzzZip.deflatedZeros(runs: (mebibytes << 20) / 258)
        var entries = try seedEntries()
        entries[1] = .init(name: "spec.json", packed: packed, expanded: expanded, crc: 0, method: 8)
        let honest = rejection(FuzzZip.build(entries), "honest \(mebibytes) MiB")
        XCTAssertTrue(
            [.entryTooLarge, .ratioExceeded].contains(honest?.code),
            "honest \(mebibytes) MiB: \(String(describing: honest))"
        )
        if expanded > PrototypeBundle.maxSpecBytes {
            XCTAssertEqual(honest, .init(.entryTooLarge, "spec.json"), "honest \(mebibytes) MiB")
        }
        // A lying declared size cannot buy more output than the byte budget allows.
        entries[1].expanded = 100
        let lying = rejection(FuzzZip.build(entries), "lying \(mebibytes) MiB")
        XCTAssertTrue(
            [.entryTooLarge, .ratioExceeded, .sizeMismatch].contains(lying?.code),
            "lying \(mebibytes) MiB: \(String(describing: lying))"
        )
    }

    func testZipBomb01MiBRejectsWithoutInflatingPastTheCap() throws { try bombRejects(mebibytes: 1) }
    func testZipBomb02MiBRejectsWithoutInflatingPastTheCap() throws { try bombRejects(mebibytes: 2) }
    func testZipBomb04MiBRejectsWithoutInflatingPastTheCap() throws { try bombRejects(mebibytes: 4) }
    func testZipBomb08MiBRejectsWithoutInflatingPastTheCap() throws { try bombRejects(mebibytes: 8) }
    func testZipBomb16MiBRejectsWithoutInflatingPastTheCap() throws { try bombRejects(mebibytes: 16) }

    func testZipBombAssetEntriesAndEntryFloodsReject() throws {
        let (packed, expanded) = FuzzZip.deflatedZeros(runs: (16 << 20) / 258)
        let bomb = FuzzZipEntry(
            name: "assets/\(String(repeating: "0", count: 64)).png",
            packed: packed,
            expanded: expanded,
            crc: 0,
            method: 8
        )
        var single = try seedEntries()
        single.append(bomb)
        XCTAssertNotNil(rejection(FuzzZip.build(single), "asset bomb"))
        var flood = try seedEntries()
        for index in 0 ..< 34 {
            var copy = bomb
            copy.name = "assets/\(String(format: "%064x", index)).png"
            flood.append(copy)
        }
        XCTAssertNotNil(rejection(FuzzZip.build(flood), "flood"))
        flood.append(bomb)
        XCTAssertEqual(rejection(FuzzZip.build(flood), "flood plus one")?.code, .tooManyEntries)
    }

    // MARK: - Hostile JSON inside an otherwise valid archive

    private func nested(_ depth: Int, _ open: String, _ close: String, _ leaf: String) -> Data {
        Data((String(repeating: open, count: depth) + leaf + String(repeating: close, count: depth)).utf8)
    }

    private func hostileJSON() -> [(String, Data)] {
        let bom = Data([0xEF, 0xBB, 0xBF])
        return [
            ("duplicate key", Data(#"{"a":1,"a":2}"#.utf8)),
            ("escaped duplicate key", Data(#"{"a":1,"\u0061":2}"#.utf8)),
            ("nested duplicate key", Data(#"{"x":{"a":1,"a":1}}"#.utf8)),
            ("depth 63", nested(63, "[", "]", "0")),
            ("depth 64", nested(64, "[", "]", "0")),
            ("depth 65", nested(65, "[", "]", "0")),
            ("depth 5000", nested(5000, "[", "]", "0")),
            ("depth 70000", nested(70000, "[", "]", "0")),
            ("object depth 5000", nested(5000, #"{"k":"#, "}", "0")),
            ("bom", bom + Data("{}".utf8)),
            ("double bom", bom + bom + Data("{}".utf8)),
            ("invalid utf8 in string", Data([0x7B, 0x22, 0x61, 0x22, 0x3A, 0x22, 0xFF, 0xFE, 0x22, 0x7D])),
            ("overlong utf8 key", Data([0x7B, 0x22, 0xC0, 0xAF, 0x22, 0x3A, 0x31, 0x7D])),
            ("encoded surrogate", Data([0x7B, 0x22, 0x61, 0x22, 0x3A, 0x22, 0xED, 0xA0, 0x80, 0x22, 0x7D])),
            ("lone high surrogate escape", Data(#"{"a":"\ud800"}"#.utf8)),
            ("lone low surrogate escape", Data(#"{"a":"\udc00"}"#.utf8)),
            ("lone surrogate key", Data(#"{"\ud800":1}"#.utf8)),
            ("surrogate pair key", Data(#"{"a":"\ud800\udc00","\ud800\udc00":1}"#.utf8)),
            ("proto duplicate", Data(#"{"__proto__":1,"__proto__":2}"#.utf8)),
            ("huge exponent", Data(#"{"a":1e999}"#.utf8)),
            ("tiny exponent", Data(#"{"a":-0,"b":1E2,"c":0.1e-400}"#.utf8)),
            ("huge integer", Data(("{\"a\":" + String(repeating: "9", count: 5000) + "}").utf8)),
            ("leading zero", Data(#"{"a":01}"#.utf8)),
            ("single quotes", Data("{'a':1}".utf8)),
            ("trailing comma", Data(#"{"a":1,}"#.utf8)),
            ("nan", Data(#"{"a":NaN}"#.utf8)),
            ("nul", Data([0])),
            ("empty", Data()),
            ("two documents", Data(#"{"a":1} {"b":2}"#.utf8)),
            ("line separators", Data("{\"a\":\"\u{2028}\u{2029}\"}".utf8)),
            ("nul escape", Data(#"{"a":"\u0000"}"#.utf8)),
            ("unterminated string", Data(#"{"a":"abc"#.utf8)),
            ("unterminated escape", Data(#"{"a":"\"#.utf8)),
        ]
    }

    private func rewrite(spec: Data) throws -> Data {
        var entries = try seedEntries()
        let oldSha = PrototypeBundle.sha256(entries[1].packed)
        let manifest = (String(data: entries[0].packed, encoding: .utf8) ?? "")
            .replacingOccurrences(of: oldSha, with: PrototypeBundle.sha256(spec))
        entries[0] = .stored("bundle.json", Data(manifest.utf8))
        entries[1] = .stored("spec.json", spec)
        return FuzzZip.build(entries)
    }

    func testHostileSpecJSONNeverTraps() throws {
        for (label, spec) in hostileJSON() {
            try assertTotal(rewrite(spec: spec), "spec \(label)")
        }
    }

    func testHostileSpecJSONFailsWithSpecCodes() throws {
        let invalidJSON = [
            "duplicate key", "escaped duplicate key", "nested duplicate key", "depth 65", "depth 5000",
            "depth 70000", "object depth 5000", "invalid utf8 in string", "overlong utf8 key",
            "encoded surrogate", "proto duplicate", "leading zero", "single quotes", "trailing comma",
            "nan", "nul", "empty", "two documents", "unterminated string", "unterminated escape",
        ]
        let all = Dictionary(uniqueKeysWithValues: hostileJSON())
        for label in invalidJSON {
            let error = try rejection(rewrite(spec: XCTUnwrap(all[label], label)), label)
            XCTAssertEqual(error, .init(.specInvalidJSON, "spec.json"), label)
        }
        for label in ["depth 63", "depth 64", "bom", "double bom"] {
            // Valid JSON that is not a prototype spec (or has stray BOMs) fails schema validation.
            let error = try rejection(rewrite(spec: XCTUnwrap(all[label], label)), label)
            XCTAssertTrue(
                [.specInvalid, .specInvalidJSON].contains(error?.code),
                "\(label): \(String(describing: error))"
            )
        }
    }

    func testHostileManifestJSONNeverTraps() throws {
        for (label, manifest) in hostileJSON() {
            var entries = try seedEntries()
            entries[0] = .stored("bundle.json", manifest)
            assertTotal(FuzzZip.build(entries), "manifest \(label)")
        }
    }

    func testHostileManifestJSONFailsWithManifestCode() throws {
        let all = Dictionary(uniqueKeysWithValues: hostileJSON())
        for label in ["duplicate key", "depth 65", "depth 5000", "invalid utf8 in string", "nul", "empty", "nan"] {
            var entries = try seedEntries()
            entries[0] = try .stored("bundle.json", XCTUnwrap(all[label], label))
            XCTAssertEqual(
                rejection(FuzzZip.build(entries), label),
                .init(.manifestInvalid, "bundle.json"),
                label
            )
        }
    }

    func testSeededRandomJSONTextNeverTraps() throws {
        var random = FuzzRandom(seed: 14159 &+ 5)
        let pieces = [
            "{", "}", "[", "]", ",", ":", "\"", "\\", "\\u", "\\ud800", "0", "-", "1e", "e+", ".", "null", "true",
            "false", "\"a\"", "\u{FEFF}", " ", "\n", "é", "99999999999999999999",
        ]
        for iteration in 0 ..< 60 {
            let text = (0 ..< 1 + random.below(40)).map { _ in random.pick(pieces) }.joined()
            try assertTotal(rewrite(spec: Data(text.utf8)), "spec text \(iteration)")
            var entries = try seedEntries()
            entries[0] = .stored("bundle.json", Data(text.utf8))
            assertTotal(FuzzZip.build(entries), "manifest text \(iteration)")
        }
    }
}
